"""Tests bloquants : chaque requête renvoie le nombre de violations (0 = succès)."""
TESTS = [
 ("T01_pk_contrat","Unicité de la clé dim_contrat.contrat_id","SELECT COUNT(*)-COUNT(DISTINCT contrat_id) FROM core.dim_contrat"),
 ("T02_pk_client","Unicité de la clé dim_client.client_id","SELECT COUNT(*)-COUNT(DISTINCT client_id) FROM core.dim_client"),
 ("T03_pk_sinistre","Unicité de fact_sinistre.sinistre_id","SELECT COUNT(*)-COUNT(DISTINCT sinistre_id) FROM core.fact_sinistre"),
 ("T04_pk_reglement","Unicité de fact_reglement.paiement_id","SELECT COUNT(*)-COUNT(DISTINCT paiement_id) FROM core.fact_reglement"),
 ("T05_pk_exposition","Unicité du grain fact_exposition (contrat, année)","SELECT COUNT(*)-COUNT(DISTINCT (contrat_id, annee)) FROM core.fact_exposition"),
 ("T06_fk_contrat_client","Intégrité : tout contrat pointe un client du cœur","SELECT COUNT(*) FROM core.dim_contrat WHERE client_id NOT IN (SELECT client_id FROM core.dim_client)"),
 ("T07_fk_sinistre_contrat","Intégrité : tout sinistre pointe un contrat du cœur","SELECT COUNT(*) FROM core.fact_sinistre WHERE contrat_id NOT IN (SELECT contrat_id FROM core.dim_contrat)"),
 ("T08_fk_reglement_sinistre","Intégrité : tout règlement pointe un sinistre du cœur","SELECT COUNT(*) FROM core.fact_reglement WHERE sinistre_id NOT IN (SELECT sinistre_id FROM core.fact_sinistre)"),
 ("T09_fk_dates","Intégrité : toutes les clés de date existent dans dim_date","""SELECT (SELECT COUNT(*) FROM core.fact_sinistre WHERE date_survenance_key NOT IN (SELECT date_key FROM core.dim_date) OR date_declaration_key NOT IN (SELECT date_key FROM core.dim_date)) + (SELECT COUNT(*) FROM core.fact_reglement WHERE date_key NOT IN (SELECT date_key FROM core.dim_date)) + (SELECT COUNT(*) FROM core.dim_contrat WHERE date_effet_key NOT IN (SELECT date_key FROM core.dim_date))"""),
 ("T10_exposition_positive","Exposition strictement positive et <= 1 année-police par ligne","SELECT COUNT(*) FROM core.fact_exposition WHERE exposition_annee_police <= 0 OR exposition_annee_police > 1.0000001 OR jours_couverture <= 0"),
 ("T11_recon_reglements_lignes","Réconciliation règlements : lignes brutes = cœur + quarantaine","""SELECT ABS((SELECT COUNT(*) FROM raw.reglements) - (SELECT COUNT(*) FROM core.fact_reglement) - (SELECT COUNT(*) FROM quarantine.rows WHERE entity='reglement'))"""),
 ("T12_recon_reglements_montants","Réconciliation règlements : montant brut = montant cœur + montant en quarantaine (écart < 1 centime)","""SELECT CASE WHEN ABS((SELECT SUM(COALESCE(TRY_CAST(montant AS DOUBLE), TRY_CAST(montant_eur AS DOUBLE))) FROM raw.reglements) - (SELECT SUM(montant)::DOUBLE FROM core.fact_reglement) - (SELECT COALESCE(SUM(r.montant),0) FROM prep.reglements r JOIN quarantine.rows q ON q.entity='reglement' AND q.record_key=r.paiement_id::VARCHAR AND q.source_file=r._source_file)) < 0.01 THEN 0 ELSE 1 END"""),
 ("T13_recon_contrats","Réconciliation contrats : brut = cœur + quarantaine (clés distinctes)","SELECT ABS((SELECT COUNT(*) FROM raw.contrats) - (SELECT COUNT(*) FROM core.dim_contrat) - (SELECT COUNT(DISTINCT record_key) FROM quarantine.rows WHERE entity='contrat'))"),
 ("T14_recon_clients","Réconciliation clients : brut = clients du cœur + alias fusionnés","SELECT ABS((SELECT COUNT(*) FROM raw.clients) - (SELECT COUNT(*) FROM core.dim_client) - (SELECT COUNT(*) FROM core.client_alias))"),
 ("T15_recon_sinistres","Réconciliation sinistres : brut = cœur + quarantaine","SELECT ABS((SELECT COUNT(*) FROM raw.sinistres) - (SELECT COUNT(*) FROM core.fact_sinistre) - (SELECT COUNT(*) FROM quarantine.rows WHERE entity='sinistre'))"),
 ("T16_alias_survivants","Tout alias client pointe un survivant présent dans dim_client","SELECT COUNT(*) FROM core.client_alias WHERE client_id_survivant NOT IN (SELECT client_id FROM core.dim_client)"),
 ("T17_dedup_email","Aucun email_hash en double dans dim_client","SELECT COUNT(*)-COUNT(DISTINCT email_hash) FROM core.dim_client"),
 ("T18_quarantaine_motif","Toute ligne en quarantaine porte une règle et un motif","SELECT COUNT(*) FROM quarantine.rows WHERE rule_id IS NULL OR motif IS NULL OR motif = ''"),
 ("T19_journal_vs_brut","Journal d'ingestion = contenu du brut (par fichier, dernier chargement)","""SELECT COUNT(*) FROM (SELECT _source_file f, COUNT(*) n FROM (SELECT _source_file FROM raw.clients UNION ALL SELECT _source_file FROM raw.contrats UNION ALL SELECT _source_file FROM raw.sinistres UNION ALL SELECT _source_file FROM raw.reglements UNION ALL SELECT _source_file FROM raw.audits) GROUP BY 1) r LEFT JOIN (SELECT file, ARG_MAX(rows_loaded, logged_at) rl FROM ops.ingestion_log WHERE status='LOADED' GROUP BY file) j ON j.file=r.f WHERE j.rl IS DISTINCT FROM r.n"""),
 ("T20_prime_acquise_bornee","Prime acquise <= prime annuelle du contrat","SELECT COUNT(*) FROM core.fact_exposition f JOIN core.dim_contrat c USING (contrat_id) WHERE f.prime_acquise > c.prime_annuelle + 0.001"),
 ("M01_mart_prime_mois","Mart portefeuille_mois : prime acquise et exposition = fact_exposition (écart < 1 EUR)","SELECT CASE WHEN ABS((SELECT SUM(prime_acquise) FROM marts.portefeuille_mois) - (SELECT SUM(prime_acquise) FROM core.fact_exposition)) < 1 AND ABS((SELECT SUM(exposition) FROM marts.portefeuille_mois) - (SELECT SUM(exposition_annee_police) FROM core.fact_exposition)) < 0.001 THEN 0 ELSE 1 END"),
 ("M02_mart_paye_mois","Mart portefeuille_mois : sinistres payés = fact_sinistre","SELECT CASE WHEN ABS((SELECT SUM(paye) FROM marts.portefeuille_mois) - (SELECT SUM(montant_regle)::DOUBLE FROM core.fact_sinistre)) < 1 AND (SELECT SUM(sinistres_declares) FROM marts.portefeuille_mois) = (SELECT COUNT(*) FROM core.fact_sinistre) THEN 0 ELSE 1 END"),
 ("M03_mart_technique","Mart technique_segment : primes, payé, exposition et résiliations = cœur","SELECT CASE WHEN ABS((SELECT SUM(prime_acquise) FROM marts.technique_segment) - (SELECT SUM(prime_acquise) FROM core.fact_exposition)) < 1 AND ABS((SELECT SUM(paye) FROM marts.technique_segment) - (SELECT SUM(montant_regle)::DOUBLE FROM core.fact_sinistre)) < 1 AND (SELECT SUM(resiliations) FROM marts.technique_segment) = (SELECT COUNT(*) FROM core.dim_contrat WHERE date_resiliation IS NOT NULL) THEN 0 ELSE 1 END"),
 ("M04_contributions_somme","Contributions des segments : somme = variation du ratio global (chaque année et périmètre)","SELECT COUNT(*) FROM (SELECT annee, perimetre, SUM(contribution) AS s FROM marts.contribution_segment GROUP BY 1, 2) x JOIN marts.decomposition_annuelle d ON d.annee = x.annee AND d.perimetre = x.perimetre JOIN marts.decomposition_annuelle p ON p.annee = x.annee - 1 AND p.perimetre = x.perimetre WHERE ABS(x.s - (d.ratio - p.ratio)) > 1e-9"),
 ("M05_pareto_ferme","Courbe de Pareto : le dernier point cumule 100 % de la valeur","SELECT COUNT(*) FROM marts.pareto_valeur WHERE pct_clients = 100 AND ABS(part_cumulee_valeur - 1) > 1e-9"),
 ("M06_retention_bornee","Rétention : 0 <= retenus <= éligibles","SELECT COUNT(*) FROM marts.retention_cohorte WHERE contrats_retenus > contrats_eligibles OR contrats_retenus < 0"),
 ("M07_valeur_client","Valeur client : somme = primes acquises - sinistres payés du cœur","SELECT CASE WHEN ABS((SELECT SUM(valeur) FROM marts.valeur_client) - ((SELECT SUM(prime_acquise) FROM core.fact_exposition) - (SELECT SUM(montant_regle)::DOUBLE FROM core.fact_sinistre))) < 1 THEN 0 ELSE 1 END"),
 ("T21_encodage_texte","Aucun texte mal encodé (caractères Ã) dans la quarantaine, les libellés de garantie et les règles","SELECT (SELECT COUNT(*) FROM quarantine.rows WHERE motif LIKE '%Ã%') + (SELECT COUNT(*) FROM core.dim_garantie WHERE libelle LIKE '%Ã%') + (SELECT COUNT(*) FROM dq.rule_results WHERE description LIKE '%Ã%' OR treatment LIKE '%Ã%')"),
]
